def median(values):
    if not values:
        raise ValueError("median() arg is an empty sequence")
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2.0
