import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("TTL must be greater than 0")

        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        # OrderedDict stores: key -> (value, expiry_time)
        self._cache = OrderedDict()

    def _purge_expired(self):
        current_time = self.clock()
        # Find keys that are expired
        expired_keys = [
            key for key, (_, expiry) in self._cache.items()
            if current_time >= expiry
        ]
        for key in expired_keys:
            del self._cache[key]

    def put(self, key, value):
        self._purge_expired()

        expiry = self.clock() + self.ttl

        if key in self._cache:
            # Update existing key and move to end (most recently used)
            self._cache.move_to_end(key)
        self._cache[key] = (value, expiry)

        # Enforce capacity
        while len(self._cache) > self.capacity:
            # Try to purge expired first before evicting LRU
            self._purge_expired()
            if len(self._cache) > self.capacity:
                # Pop the least recently used item (first item in OrderedDict)
                self._cache.popitem(last=False)

    def get(self, key):
        self._purge_expired()

        if key not in self._cache:
            return None

        value, expiry = self._cache[key]
        if self.clock() >= expiry:
            del self._cache[key]
            return None

        # Move to most recently used
        self._cache.move_to_end(key)
        return value

    def __len__(self):
        self._purge_expired()
        return len(self._cache)

    def keys(self):
        self._purge_expired()
        return list(self._cache.keys())
