class Scheduler:
    def __init__(self):
        self.tasks = {}  # name -> dict of task info
        self.errors = []
        self._insertion_counter = 0

    def schedule(self, name, run_at, callback, every=None):
        if name in self.tasks:
            raise ValueError(f"Task with name '{name}' already exists.")
        if every is not None and every <= 0:
            raise ValueError("Parameter 'every' must be greater than 0.")

        self._insertion_counter += 1
        self.tasks[name] = {
            'run_at': run_at,
            'callback': callback,
            'every': every,
            'order': self._insertion_counter
        }

    def cancel(self, name):
        if name in self.tasks:
            del self.tasks[name]
            return True
        return False

    def pending(self):
        # Sort by run_at, then by insertion order
        sorted_tasks = sorted(
            self.tasks.items(),
            key=lambda item: (item[1]['run_at'], item[1]['order'])
        )
        return [(task['run_at'], name) for name, task in sorted_tasks]

    def run_due(self, now):
        # Find all tasks due at or before 'now', sorted correctly
        due_items = [
            (task['run_at'], name, task)
            for name, task in self.tasks.items()
            if task['run_at'] <= now
        ]
        due_items.sort(key=lambda x: (x[0], x[2]['order']))

        run_names = []

        for _, name, task in due_items:
            # Task might have been cancelled by an earlier callback in the same run_due call
            if name not in self.tasks:
                continue

            # Verify it's still due (though it should be, unless mutated somehow)
            if task['run_at'] > now:
                continue

            run_names.append(name)

            # Execute callback
            try:
                task['callback']()
            except Exception as e:
                self.errors.append((name, e))

            # Re-check existence in case callback cancelled itself
            if name not in self.tasks:
                continue

            if task['every'] is not None:
                # Move run_at forward in steps of 'every' until it is greater than 'now'
                while task['run_at'] <= now:
                    task['run_at'] += task['every']
            else:
                # One-time task, remove it
                del self.tasks[name]

        return run_names
