def evaluate(expr, variables=None):
    if variables is None:
        variables = {}

    if not isinstance(expr, str) or not expr.strip():
        raise ExprError("Empty expression")

    # Pre-check for invalid characters and implicit multiplication patterns
    # Check for unknown characters (anything not digit, letter, underscore, operator, parenthesis, comma, dot, space)
    # Valid tokens: a-z, A-Z, 0-9, +, -, *, /, ^, (, ), ,, ., _
    for char in expr:
        if not (char.isalnum() or char in "+-*/^(),._ "):
            raise ExprError(f"Unknown character: {char}")

