    # Actually, standard says: "Numbers are written with digits and an optional decimal point (3, 2.5, .5 is not allowed, 5. is not allowed)."
    # This means a number must start with a digit, and if it has a decimal point, it must be followed by at least one digit.

    tokens = []
    i = 0
    n = len(expr)

