        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in "+-*/^(),":
            tokens.append((c, i))
            i += 1
        elif c.isalpha() or c == '_':
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            tokens.append((expr[start:i], start))
        elif c.isdigit() or c == '.':
            # Check number format
            start = i
            if c == '.':
                raise ExprError("Numbers cannot start with a decimal point")
            while i < n and expr[i].isdigit():
                i += 1
            if i < n and expr[i] == '.':
                i += 1
