            num_str = expr[start:i]
            tokens.append((num_str, start))
        else:
            raise ExprError(f"Unknown character: {c}")

    if not tokens:
        raise ExprError("Empty expression")

    # Validate token sequence and handle implicit multiplication / syntax errors
    # Process tokens to a clean list of types/values

    # Check for binary vs unary operators, missing operands, etc.
    # Let's write a recursive descent parser.

    class Parser:
        def __init__(self, toks):
            self.toks = toks
            self.pos = 0
            self.length = len(toks)

        def peek(self):
            if self.pos < self.length:
                return self.toks[self.pos][0]
            return None

        def consume(self):
            if self.pos < self.length:
                val = self.toks[self.pos]
                self.pos += 1
                return val
            return None

