class OutOfStock(Exception):
    pass


class Inventory:
    def __init__(self, stock=None):
        if stock is not None:
            for item, qty in stock.items():
                if qty <= 0:
                    raise ValueError("Quantity must be positive")
            self._stock = dict(stock)
        else:
            self._stock = {}

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        current = self.stock(item)
        if qty > current:
            raise OutOfStock(f"Not enough stock for {item}")

        new_qty = current - qty
        if new_qty == 0:
            self._stock.pop(item, None)
        else:
            self._stock[item] = new_qty


def fulfil(inventory, order):
    for item, qty in order.items():
        if qty <= 0:
            raise ValueError("Order quantity must be positive")

    # Check all items before making any changes (all-or-nothing)
    for item, qty in order.items():
        if inventory.stock(item) < qty:
            raise OutOfStock(f"Not enough stock for {item}")

    total = 0
    for item, qty in order.items():
        inventory.remove(item, qty)
        total += qty
    return total
