def _tokenize(template):
    # Tokens: TEXT, VAR, BLOCK
    # We scan through the template using a regex to find {{, }}, `{%`, and `%}`.
    # Unclosed `{{` or `{%` are treated as plain text according to rule 7.
    tokens = []
    i = 0
    n = len(template)

    while i < n:
        # Find next opening tag
        m_var = template.find('{{', i)
        m_block = template.find('{%', i)

        # Determine which comes first
        if m_var == -1 and m_block == -1:
            tokens.append(('TEXT', template[i:]))
            break
        elif m_var != -1 and (m_block == -1 or m_var < m_block):
            # Check if closed
            end = template.find('}}', m_var + 2)
            if end == -1:
                # Rule 7: unclosed is plain text
                tokens.append(('TEXT', template[i:]))
                break
            else:
                if m_var > i:
                    tokens.append(('TEXT', template[i:m_var]))
                content = template[m_var + 2:end].strip()
                tokens.append(('VAR', content))
                i = end + 2
        else:
            # Block tag comes first
            end = template.find('%}', m_block + 2)
            if end == -1:
                # Rule 7: unclosed is plain text
                tokens.append(('TEXT', template[i:]))
                break
            else:
                if m_block > i:
                    tokens.append(('TEXT', template[i:m_block]))
                content = template[m_block + 2:end].strip()
                tokens.append(('BLOCK', content))
                i = end + 2
    return tokens

def _parse(tokens):
    # Returns an AST tree of nodes.
    # Nodes can be:
    # ('TEXT', text)
    # ('VAR', path, filter_name)
    # ('IF', not_flag, path, true_body, false_body)
    # ('FOR', name, path, body)

    pos = [0]

    def parse_block(end_tags):
        body = []
        while pos[0] < len(tokens):
            t_type, t_content = tokens[pos[0]]
            if t_type == 'TEXT':
                body.append(('TEXT', t_content))
                pos[0] += 1
            elif t_type == 'VAR':
                # Parse path | filter
                if '|' in t_content:
                    parts = t_content.split('|', 1)
                    path = parts[0].strip()
                    filt = parts[1].strip()
                else:
                    path = t_content
                    filt = None
                body.append(('VAR', path, filt))
                pos[0] += 1
            elif t_type == 'BLOCK':
                parts = t_content.split()
                if not parts:
                    raise ValueError("Empty block tag")
                tag = parts[0]

                if tag in end_tags:
                    return body

                if tag == 'if':
                    if len(parts) < 2:
                        raise ValueError("Invalid if tag")
                    if parts[1] == 'not':
                        if len(parts) < 3:
                            raise ValueError("Invalid if not tag")
                        not_flag = True
                        path = parts[2]
                    else:
                        not_flag = False
                        path = parts[1]

                    pos[0] += 1 # consume if
                    true_body = parse_block(['endif', 'else'])

                    current_token = tokens[pos[0]] if pos[0] < len(tokens) else None
                    if current_token and current_token[0] == 'BLOCK' and current_token[1] == 'else':
                        pos[0] += 1 # consume else
                        false_body = parse_block(['endif'])
                        # consume endif
                        if pos[0] < len(tokens) and tokens[pos[0]][0] == 'BLOCK' and tokens[pos[0]][1] == 'endif':
                            pos[0] += 1
                        else:
                            raise ValueError("Missing endif after else")
                    else:
                        false_body = []
                        if pos[0] < len(tokens) and tokens[pos[0]][0] == 'BLOCK' and tokens[pos[0]][1] == 'endif':
                            pos[0] += 1
                        else:
                            raise ValueError("Missing endif")

                    body.append(('IF', not_flag, path, true_body, false_body))

                elif tag == 'for':
                    # expected: for name in path
                    if len(parts) < 4 or parts[2] != 'in':
                        raise ValueError("Invalid for tag syntax")
                    name = parts[1]
                    path = parts[3]

                    pos[0] += 1 # consume for
                    loop_body = parse_block(['endfor'])
                    if pos[0] < len(tokens) and tokens[pos[0]][0] == 'BLOCK' and tokens[pos[0]][1] == 'endfor':
                        pos[0] += 1
                    else:
                        raise ValueError("Missing endfor")

                    body.append(('FOR', name, path, loop_body))

                elif tag in ('endif', 'else', 'endfor'):
                    raise ValueError(f"Unexpected tag {tag}")
                else:
                    raise ValueError(f"Unknown block tag {tag}")
            else:
                pos[0] += 1
        return body

    ast = parse_block([])
    if pos[0] < len(tokens):
        raise ValueError("Unmatched closing tag or extra content")
    return ast

def _lookup(context, path):
    if not path:
        return None
    parts = path.split('.')
    curr = context
    for p in parts:
        if isinstance(curr, dict):
            if p in curr:
                curr = curr[p]
            else:
