        elif isinstance(curr, (list, tuple)):
            if p.isdigit():
                idx = int(p)
                if 0 <= idx < len(curr):
                    curr = curr[idx]
                else:
                    return None
            else:
                return None
        else:
            return None
    return curr

def _evaluate_node(node, context):
    ntype = node[0]
    if ntype == 'TEXT':
        return node[1]
    elif ntype == 'VAR':
        _, path, filt = node
        val = _lookup(context, path)

        if filt is not None:
            if filt == 'upper':
                s = "" if (val is None) else str(val)
                return s.upper()
            elif filt == 'lower':
                s = "" if (val is None) else str(val)
                return s.lower()
            elif filt == 'title':
                s = "" if (val is None) else str(val)
                return s.title()
            elif filt == 'length':
                if val is None:
                    return "0"
                try:
                    return str(len(val))
                except TypeError:
                    return "0"
            else:
                raise ValueError(f"Unknown filter {filt}")
        else:
            if val is None:
                return ""
            return str(val)

    elif ntype == 'IF':
        _, not_flag, path, true_body, false_body = node
        val = _lookup(context, path)
        truthy = bool(val)
        if not_flag:
            truthy = not truthy

        chosen = true_body if truthy else false_body
        return "".join(_evaluate_node(n, context) for n in chosen)

    elif ntype == 'FOR':
        _, name, path, loop_body = node
        val = _lookup(context, path)
        if not isinstance(val, (list, tuple)):
            # If missing or not a list, render nothing
            return ""

        out = []
        for item in val:
            # bind name, keeping everything else visible
            # Since context is a dict, we can shadow or copy-update
            # To avoid mutating user's context unexpectedly, we make a shallow copy or dict chain
            sub_context = dict(context)
            sub_context[name] = item
            for n in loop_body:
                out.append(_evaluate_node(n, sub_context))
        return "".join(out)
    return ""

def _evaluate(ast, context):
    return "".join(_evaluate_node(node, context) for node in ast)
